theorem ProbabilityTheory.Kernel.AEFiniteKernelSupport.extracted_1.{u_4, u_3, u_2} {S : Type u_2} {T : Type u_3}
  {U : Type u_4} [inst : MeasurableSpace S] [inst_1 : MeasurableSpace T] [inst_2 : MeasurableSpace U]
  [inst_3 : MeasurableSingletonClass U] {κ : Kernel T S} {μ : Measure T} (hκ : κ.AEFiniteKernelSupport μ) {f : S → U}
  (hf : ¬Measurable f) : (κ.map f).AEFiniteKernelSupport μ := by
  simp [map_of_not_measurable _ hf]

theorem ProbabilityTheory.Kernel.AEFiniteKernelSupport.extracted_1.{u_4, u_3, u_2} {S : Type u_2} {T : Type u_3}
  {U : Type u_4} [inst : MeasurableSpace S] [inst_1 : MeasurableSpace T] [inst_2 : MeasurableSpace U]
  [inst_3 : Countable U] [inst_4 : MeasurableSingletonClass U] {κ : Kernel T S} {μ : Measure T}
  (hκ : κ.AEFiniteKernelSupport μ) (f : U ≃ᵐ T) : MeasurableSet {x | ∃ A, (κ (f x)) (↑A)ᶜ = 0} := by
  measurability

theorem ProbabilityTheory.Kernel.AEFiniteKernelSupport.extracted_1.{u_4, u_3, u_2} {S : Type u_2} {T : Type u_3}
  {U : Type u_4} [inst : MeasurableSpace S] [inst_1 : MeasurableSpace T] [inst_2 : MeasurableSpace U]
  [inst_3 : Countable U] [inst_4 : MeasurableSingletonClass U] {κ : Kernel T S} {μ : Measure T}
  (hκ : κ.AEFiniteKernelSupport μ) (f : U ≃ᵐ T) : ∀ᵐ (x : T) ∂μ, ∃ A, (κ (f (f.symm x))) (↑A)ᶜ = 0 := by
  simp only [MeasurableEquiv.apply_symm_apply]
      exact hκ

theorem ProbabilityTheory.Kernel.FiniteKernelSupport.extracted_1.{u_4, u_3, u_2} {S : Type u_2} {T : Type u_3}
  {U : Type u_4} [inst : MeasurableSpace S] [inst_1 : MeasurableSpace T] [inst_2 : MeasurableSpace U]
  [inst_3 : MeasurableSingletonClass S] [inst_4 : MeasurableSingletonClass U] {κ : Kernel T S} {η : Kernel (T × S) U}
  (hκ : κ.FiniteKernelSupport) (hη : η.FiniteKernelSupport) (hκ' : IsSFiniteKernel κ) (hη' : ¬IsSFiniteKernel η) :
  (κ ⊗ₖ η).FiniteKernelSupport := by
  simp [compProd_of_not_isSFiniteKernel_right _ _ hη']

theorem ProbabilityTheory.Kernel.FiniteKernelSupport.extracted_1.{u_4, u_3, u_2} {S : Type u_2} {T : Type u_3}
  {U : Type u_4} [inst : MeasurableSpace S] [inst_1 : MeasurableSpace T] [inst_2 : MeasurableSpace U]
  [inst_3 : MeasurableSingletonClass S] [inst_4 : MeasurableSingletonClass U] {κ : Kernel T S} {η : Kernel (T × S) U}
  (hκ : κ.FiniteKernelSupport) (hη : η.FiniteKernelSupport) (hκ' : ¬IsSFiniteKernel κ) :
  (κ ⊗ₖ η).FiniteKernelSupport := by
  simp [compProd_of_not_isSFiniteKernel_left _ _ hκ']
